import 'dart:convert';
import 'dart:typed_data';

import 'package:http/http.dart' as http;

import 'auth.dart';

// BEGIN books folders: generated by tools/gen_folders.py from services/runtime/app/paths.py. Do not edit.
/// Every folder in the books tree, in order (the same list as the runtime and the web app).
const List<String> kBooksFolders = ["00 Inbox", "01 Receipts", "02 Needs a look", "03 Sales", "04 Bank statements", "05 Payroll", "06 VAT returns", "07 Reports", "03 Sales/invoices", "03 Sales/invoices/sent", "_System", "_System/audit", "_System/docs", "_System/proposals", "_System/Ledger/events", "_System/bank"];
// END books folders

/// OneDrive access for the user's own books folder. Dart port of the folder
/// logic in `apps/web/src/lib/graph.ts`.
///
/// Personal accounts live under the OneDrive app folder (`Apps/Accnomos`);
/// work accounts use `/Accnomos` in the drive root.
class GraphService {
  GraphService({http.Client? client}) : _client = client ?? http.Client();

  final http.Client _client;

  static const _graph = 'https://graph.microsoft.com/v1.0';

  /// Graph path of an item inside the books folder (path-based addressing).
  static String itemPath(AccountKind kind, [String relPath = '']) {
    final encoded =
        relPath.split('/').map(Uri.encodeComponent).join('/');
    if (kind == AccountKind.personal) {
      return relPath.isEmpty
          ? '/me/drive/special/approot'
          : '/me/drive/special/approot:/$encoded';
    }
    return relPath.isEmpty
        ? '/me/drive/root:/Accnomos'
        : '/me/drive/root:/Accnomos/$encoded';
  }

  Future<Map<String, dynamic>> _json(
    String token,
    String path, {
    String method = 'GET',
    Map<String, dynamic>? body,
  }) async {
    final response = await _client
        .send(
          http.Request(method, Uri.parse('$_graph$path'))
            ..headers['Authorization'] = 'Bearer $token'
            ..headers['Content-Type'] = 'application/json'
            ..body = body == null ? '' : json.encode(body),
        )
        .then(http.Response.fromStream)
        .timeout(const Duration(seconds: 60));
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw GraphException(
        'OneDrive refused that request (status ${response.statusCode}). '
        '${response.body.trim().take300}',
      );
    }
    if (response.body.isEmpty) return <String, dynamic>{};
    return json.decode(response.body) as Map<String, dynamic>;
  }

  /// The books root (created on first call for personal accounts).
  Future<Map<String, dynamic>> ensureRoot(
    String token,
    AccountKind kind,
  ) async {
    if (kind == AccountKind.personal) {
      return _json(token, '/me/drive/special/approot');
    }
    try {
      return await _json(token, itemPath(kind));
    } on GraphException {
      return _json(
        token,
        '/me/drive/root/children',
        method: 'POST',
        body: {
          'name': 'Accnomos',
          'folder': {},
          '@microsoft.graph.conflictBehavior': 'fail',
        },
      );
    }
  }

  /// Get-or-create a folder such as `00 Inbox`. Lookup is path-based;
  /// creation is id-based because POST on the `special/approot` alias fails.
  Future<void> ensureFolder(
    String token,
    AccountKind kind,
    String relPath,
  ) async {
    try {
      await _json(token, itemPath(kind, relPath));
      return;
    } on GraphException {
      // Missing — create it under its parent.
    }
    final parts = relPath.split('/');
    final name = parts.removeLast();
    final parent = parts.isEmpty
        ? await ensureRoot(token, kind)
        : await _ensureFolderJson(token, kind, parts.join('/'));
    await _json(
      token,
      '/me/drive/items/${parent['id']}/children',
      method: 'POST',
      body: {
        'name': name,
        'folder': {},
        '@microsoft.graph.conflictBehavior': 'fail',
      },
    );
  }

  Future<Map<String, dynamic>> _ensureFolderJson(
    String token,
    AccountKind kind,
    String relPath,
  ) async {
    try {
      return await _json(token, itemPath(kind, relPath));
    } on GraphException {
      // Missing — create it under its parent.
    }
    final parts = relPath.split('/');
    final name = parts.removeLast();
    final parent = parts.isEmpty
        ? await ensureRoot(token, kind)
        : await _ensureFolderJson(token, kind, parts.join('/'));
    return _json(
      token,
      '/me/drive/items/${parent['id']}/children',
      method: 'POST',
      body: {
        'name': name,
        'folder': {},
        '@microsoft.graph.conflictBehavior': 'fail',
      },
    );
  }

  /// The books folder itself (or a subfolder such as `05 VAT returns`),
  /// as raw JSON. Used to resolve the id before listing children.
  Future<Map<String, dynamic>> folderJson(
    String token,
    AccountKind kind, [
    String relPath = '',
  ]) async {
    if (relPath.isEmpty) return ensureRoot(token, kind);
    return _json(token, itemPath(kind, relPath));
  }

  /// OneDrive web URL of one file or folder in the books tree, for opening
  /// a cited file. Null when it cannot be read. Mirrors `getFileWebUrl` in
  /// `apps/web/src/lib/graph.ts`.
  Future<String?> fileWebUrl(
    String token,
    AccountKind kind,
    String relPath,
  ) async {
    try {
      final trimmed = relPath.replaceAll(RegExp(r'/+$'), '');
      final json = await _json(
        token,
        '${itemPath(kind, trimmed)}?\$select=webUrl',
      );
      final url = (json['webUrl'] ?? '').toString();
      return url.isEmpty ? null : url;
    } catch (_) {
      return null;
    }
  }

  /// Children of the books folder (or a subfolder), folders first.
  /// Counts come from the `folder.childCount` facet; files carry `size`,
  /// `lastModifiedDateTime` and `webUrl` for the "Open" button.
  Future<List<DriveItem>> listChildren(
    String token,
    AccountKind kind, [
    String relPath = '',
  ]) async {
    final folder = await folderJson(token, kind, relPath);
    final id = (folder['id'] ?? '').toString();
    if (id.isEmpty) {
      throw GraphException('Could not open that folder. Try again.');
    }
    final json = await _json(
        token, '/me/drive/items/$id/children?\$top=200');
    final raw = json['value'];
    final items = <DriveItem>[];
    if (raw is List) {
      for (final entry in raw) {
        if (entry is Map) {
          items.add(DriveItem.fromJson(Map<String, dynamic>.from(entry)));
        }
      }
    }
    items.sort((a, b) {
      if (a.isFolder != b.isFolder) return a.isFolder ? -1 : 1;
      return a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });
    return items;
  }

  /// Download a filed document for the Review image viewer: the same
  /// `:/content` GET the web's `getFileBlob` makes. [relPath] is the
  /// proposal's `file_path`, relative to the books folder.
  Future<Uint8List> fileBytes(
    String token,
    AccountKind kind,
    String relPath,
  ) async {
    final response = await _client
        .get(
          Uri.parse('$_graph${itemPath(kind, relPath)}:/content'),
          headers: {'Authorization': 'Bearer $token'},
        )
        .timeout(const Duration(seconds: 60));
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw GraphException(
        'Could not open that document (status ${response.statusCode}).',
      );
    }
    return response.bodyBytes;
  }

  /// Small-file upload (up to 4 MB), the same call the web's
  /// `UploadToInbox.tsx` makes: Graph PUT to the `00 Inbox` folder.
  Future<void> putFileBytes({
    required String token,
    required AccountKind kind,
    required String relPath,
    required List<int> bytes,
    required String contentType,
  }) async {
    final response = await _client
        .put(
          Uri.parse('$_graph${itemPath(kind, relPath)}:/content'),
          headers: {
            'Authorization': 'Bearer $token',
            'Content-Type': contentType,
          },
          body: bytes,
        )
        .timeout(const Duration(seconds: 120));
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw GraphException(
        'Upload failed (status ${response.statusCode}). '
        '${response.body.trim().take300}',
      );
    }
  }

  void close() => _client.close();
}

/// One file or folder inside the user's books folder, as returned by
/// `GET /me/drive/items/{id}/children`.
class DriveItem {
  DriveItem({
    required this.id,
    required this.name,
    required this.isFolder,
    this.childCount,
    this.size,
    this.lastModified,
    this.webUrl,
  });

  final String id;
  final String name;
  final bool isFolder;

  /// Entries inside this folder (the `folder.childCount` facet).
  final int? childCount;

  /// File size in bytes (files only).
  final int? size;

  final DateTime? lastModified;

  /// OneDrive web link, opened by the "Open" button.
  final String? webUrl;

  factory DriveItem.fromJson(Map<String, dynamic> json) {
    DateTime? modified;
    final rawDate = json['lastModifiedDateTime']?.toString();
    if (rawDate != null && rawDate.isNotEmpty) {
      modified = DateTime.tryParse(rawDate)?.toLocal();
    }
    int? childCount;
    if (json['folder'] is Map) {
      final count = (json['folder'] as Map)['childCount'];
      if (count is num) childCount = count.toInt();
    }
    int? size;
    if (json['size'] is num) size = (json['size'] as num).toInt();
    return DriveItem(
      id: (json['id'] ?? '').toString(),
      name: (json['name'] ?? 'Unnamed').toString(),
      isFolder: json['folder'] is Map,
      childCount: childCount,
      size: size,
      lastModified: modified,
      webUrl: json['webUrl']?.toString(),
    );
  }

  /// `3 items`, `1 item` or `Empty` for folders.
  String get countLabel {
    if (!isFolder) return '';
    final n = childCount ?? 0;
    if (n == 0) return 'Empty';
    return '$n item${n == 1 ? '' : 's'}';
  }

  /// `12.4 KB`, `3.1 MB` or `812 bytes`.
  String get sizeLabel {
    final bytes = size ?? 0;
    if (bytes >= 1024 * 1024) {
      return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';
    }
    if (bytes >= 1024) {
      return '${(bytes / 1024).toStringAsFixed(1)} KB';
    }
    return '$bytes bytes';
  }

  /// `21 Oct 2026` in UK order, or '' when unknown.
  String get dateLabel {
    final d = lastModified;
    if (d == null) return '';
    const months = [
      'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
      'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
    ];
    return '${d.day} ${months[d.month - 1]} ${d.year}';
  }
}

/// Error from OneDrive. [message] is safe to show in the UI.
class GraphException implements Exception {
  GraphException(this.message);
  final String message;

  @override
  String toString() => message;
}

extension on String {
  String get take300 =>
      length > 300 ? '${substring(0, 300)}…' : this;
}
